  }
  h1 { font-size: 1.25rem; font-weight: 600; letter-spacing: 0.02em; }
  .hud {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    align-items: center;
    justify-content: center;
    font-variant-numeric: tabular-nums;
  }
  .hud span { opacity: 0.85; }
  .hud strong { color: #7dd3fc; }
  button#reset {
    background: #1e3a5f;
    color: #e7ecf1;
